exercise.referenceSolution:
class Source { int id_; public: explicit Source(int id) : id_(id) {} int id() const { return id_; } virtual int read() const = 0; virtual ~Source() = default; };
class Sample : public Source { int value_; public: Sample(int id,int value) : Source(id), value_(value) {} int read() const override { return value_; } };
int solve(int a,int b) { Sample x{a,b}; const Source& s=x; return s.id()+s.read(); }
